        page=f'''<!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{escape(title)} · JV Busca</title><link rel="icon" href="./assets/jv-mascot.png"><link rel="stylesheet" href="./shop.css?v=13"><link rel="stylesheet" href="./jv.css?v=13"><script defer src="./privacy.js?v=13"></script></head><body><header><div class="wrap header-row"><a class="brand" href="./"><img class="brand-mascot" src="./assets/jv-mascot.png" alt=""><b>JV</b> BUSCA</a><a class="button" href="./">Voltar aos produtos</a></div></header><main class="wrap legal-content">{body}</main><footer class="wrap">{FOOTER_LINKS}</footer>{PRIVACY_UI}</body></html>'''
